'use strict';
const M=ReportModel,$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',folder:'M3 7V5h6l2 2h10v13H3z',file:'M6 3h8l4 4v14H6zM14 3v5h5M9 12h6M9 16h6',image:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M16 7h.01',check:'M5 12l4 4L19 6',list:'M9 6h12M9 12h12M9 18h12M3 6h1M3 12h1M3 18h1',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',chevron:'M9 5l7 7-7 7',down:'M5 9l7 7 7-7',plus:'M12 5v14M5 12h14',upload:'M12 16V3M7 8l5-5 5 5M3 15v6h18v-6',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4zM10 21h4',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14M15 15l6 6',help:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M9 9a3 3 0 1 1 4 3v2M12 17h.01',download:'M12 3v13M7 11l5 5 5-5M3 17v4h18v-4',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v5l3 2',warning:'M12 3L2 21h20zM12 9v5M12 17h.01',arrow:'M4 12h16M14 6l6 6-6 6',copy:'M8 8h13v13H8zM16 8V3H3v13h5',trash:'M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7M14 10v7',menu:'M3 6h18M3 12h18M3 18h18',close:'M5 5l14 14M5 19L19 5',chart:'M4 3v18h17M7 16l5-6 4 3 5-8',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M2 21v-3a7 7 0 0 1 14 0v3M17 4a4 4 0 0 1 0 7M19 15a6 6 0 0 1 3 6',mail:'M3 5h18v14H3zM3 5l9 8 9-8',link:'M10 14l4-4M8 16l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.file}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const labels={dashboard:'ภาพรวมการทำงาน',projects:'โครงการทั้งหมด',assets:'ลูกค้าและอุปกรณ์',worklist:'งานของช่างเทคนิค',checklist:'แบบตรวจสอบหน้างาน',photos:'คลังภาพโครงการ',tests:'ผลทดสอบสมรรถนะ',documents:'เอกสารและใบสอบเทียบ',inbox:'ตรวจความครบถ้วน',builder:'Report Builder',templates:'Template Library',designer:'Template Designer',review:'ตรวจทานทางวิศวกรรม',approval:'การอนุมัติและส่งออก',settings:'ตั้งค่าและประวัติ'};
const secLabels={cover:['หน้าปกรายงาน','Cover page'],inspection:['ผลการตรวจสอบ','Inspection checklist'],performance:['ผลทดสอบสมรรถนะ','Flow & pressure record'],findings:['สรุปผลและข้อเสนอแนะ','Findings & recommendations'],appendix:['ภาพหลักฐานและภาคผนวก','Evidence & appendix']};
const categories=['ยังไม่จัดหมวด','Fire Pump','Jockey Pump','Controller','Pressure Gauge','Maintenance','Defect'];
let state;try{state=JSON.parse(localStorage.getItem('idc-report-v1'))||M.seed();if(state.version!==1||!state.projects?.length)state=M.seed()}catch{state=M.seed()}
let view='builder',section='cover',tab='content',photos=[],documents=[],db,photoUrls=new Map(),search='',zoom=100,storageError=false;
const project=()=>state.projects.find(p=>p.id===state.active)||state.projects[0],projectPhotos=()=>photos.filter(p=>p.projectId===project().id),projectDocs=()=>documents.filter(d=>d.projectId===project().id),locked=()=>['SUBMITTED','APPROVED'].includes(project().status);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function persist(action,old){try{localStorage.setItem('idc-report-v1',JSON.stringify(state));storageError=false}catch{storageError=true;toast('บันทึกไม่สำเร็จ: พื้นที่จัดเก็บเต็ม กรุณาสำรองข้อมูล')}if(action){project().history.unshift({at:new Date().toISOString(),action,before:old,actor:'ผู้ทดลองใช้งาน'});project().history=project().history.slice(0,150);try{localStorage.setItem('idc-report-v1',JSON.stringify(state))}catch{storageError=true}}const el=$('.save-state');if(el)el.innerHTML=storageError?'บันทึกไม่สำเร็จ':`<i class="online-dot"></i>บันทึกในเครื่องแล้ว`}
function mutate(fn,action){if(locked()){toast('ฉบับนี้ล็อกแล้ว กรุณาสร้าง Revision ใหม่ก่อนแก้ไข');return false}fn(project());project().revision++;persist(action);return true}
function navButton(v,n,count=''){return `<button class="nav-item ${view===v?'active':''}" data-view="${v}">${icon(n)}${labels[v]}${count?`<span class="count">${count}</span>`:''}</button>`}
function shell(){return `<div class="shell"><aside class="sidebar"><div class="brand"><span class="logo">IDC<span style="color:#88b6e5">.</span></span><span class="brand-line"></span><small>SMART REPORT<br>STUDIO</small></div><div class="workspace"><em>idc</em><div>IDC Engineering<small>พื้นที่ทำงาน · ต้นแบบ</small></div>${icon('down')}</div><div class="nav-label">WORKSPACE</div>${navButton('dashboard','grid')}${navButton('projects','folder',state.projects.length)}${navButton('templates','file')}<div class="nav-label" style="margin-top:24px">REPORT OPERATIONS</div>${navButton('worklist','list')}${navButton('photos','image')}${navButton('builder','spark')}${navButton('inbox','mail')}${navButton('approval','shield')}<div class="side-bottom">${navButton('settings','settings')}<div class="help-card"><strong>ข้อมูลหน้างาน → รายงานพร้อมใช้</strong><p>เพิ่มรูป ตอบคำถาม แล้วให้ระบบช่วยจัดรูปเล่มให้คุณ</p><button class="ghost" style="color:#bdcfe2;padding:0;font-size:10px" data-action="guide">ดูวิธีใช้งาน ${icon('arrow')}</button></div><div class="profile"><span class="avatar">PK</span><div>Pakorn<small>Office Coordinator · Demo</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><button class="mobile-menu ghost" data-action="menu" aria-label="เปิดเมนู">${icon('menu')}</button>Workspace ${icon('chevron')}<strong>${labels[view]}</strong></div><div class="top-right"><span class="save-state"><i class="online-dot"></i>บันทึกในเครื่อง</span><span class="divider"></span><span class="demo-badge">PROTOTYPE v0.1</span><button class="ghost" aria-label="รายการที่ต้องตรวจ" data-view="inbox">${icon('bell')}</button><span class="avatar" style="width:29px;height:29px;font-size:10px">PK</span></div></header><div class="content" id="workspace">${renderView()}</div></main></div><nav class="mobile-tabs">${[['worklist','list'],['checklist','check'],['photos','image'],['builder','file']].map(([v,i])=>`<button data-view="${v}" class="${view===v?'active':''}">${icon(i)}${{worklist:'งานของฉัน',checklist:'แบบตรวจ',photos:'รูปภาพ',builder:'รายงาน'}[v]}</button>`).join('')}</nav><div class="print-area" id="print-area"></div>`}
function render(){const scroll=window.scrollY;$('#app').innerHTML=shell();window.scrollTo(0,scroll)}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtle">${sub}</p></div><div class="actions">${actions}</div></div>`}
function badge(p=project()){const map={DRAFT:['ร่างรายงาน','blue'],SUBMITTED:['รอตรวจทาน','orange'],RETURNED:['ส่งกลับแก้ไข','orange'],APPROVED:['ล็อกฉบับตรวจทานแล้ว','green']};const [s,c]=map[p.status]||map.DRAFT;return `<span class="badge ${c}">${s}</span>`}
function completion(p=project()){return Math.round((M.questions.filter(([id])=>p.answers[id]?.value).length+p.tests.filter(t=>t.status!=='PENDING').length)/(M.questions.length+3)*100)}
function projectStrip(){const p=project();return `<div class="project-strip"><span class="project-icon">${icon('folder')}</span><div><strong>${esc(p.customer)} · ${esc(p.site)}</strong><p>${esc(p.code)} <span style="margin:0 7px">/</span> ${p.template==='PM-FP-001'?'Preventive Maintenance':'Performance Test'} <span style="margin:0 7px">/</span> ${formatDate(p.date)}</p></div><div class="right" style="width:130px"><span class="toolbar-label">ข้อมูลหน้างาน ${completion()}%</span><div class="progress"><i style="width:${completion()}%"></i></div></div><button class="ghost" data-action="select-project" aria-label="เปลี่ยนโครงการ">${icon('down')}</button></div>`}
function formatDate(s){return s?new Date(s+'T00:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'}):'ยังไม่ระบุ'}
function steps(){return `<div class="stepper">${[['projects','ข้อมูลโครงการ'],['photos','รูปและหลักฐาน'],['checklist','ข้อมูลตรวจสอบ'],['builder','จัดทำรายงาน'],['approval','ตรวจทานและส่งออก']].map(([v,t],i)=>`<button class="step ${view===v?'active':''}" data-view="${v}"><span>${i+1}</span>${t}</button>`).join('')}</div>`}
function field(name,label,value,type='text',more=''){return `<label class="field"><span>${label}</span><input data-field="${name}" type="${type}" value="${esc(value)}" ${locked()?'disabled':''} ${more}></label>`}
function renderView(){switch(view){case'builder':return builder();case'dashboard':return dashboard();case'projects':return projectsView();case'assets':return assetsView();case'templates':return templatesView();case'worklist':return worklist();case'checklist':return checklist();case'photos':return photosView();case'tests':return testsView();case'documents':return documentsView();case'inbox':case'review':return qaView();case'approval':return approvalView();case'designer':return designer();case'settings':return settingsView();default:return builder()}}
function builder(){return heading('Report Builder','เปลี่ยนข้อมูลหน้างาน ให้เป็นรายงานที่พร้อมตรวจทาน',`${badge()}<button data-action="reference">${icon('eye')}เทียบ PDF ต้นฉบับ</button><button data-action="qa">${icon('shield')}ตรวจความครบถ้วน</button><button data-action="assemble-pdf" class="primary" style="background:#0d7a5f" title="ประกอบเอกสารเดิมเป็นเล่มสมบูรณ์ 56 หน้า">${icon('spark')}สร้างเล่ม 56 หน้า (Full PDF)</button><button class="primary" data-action="print">${icon('download')}ส่งออก PDF</button>`)+projectStrip()+steps()+`<div class="notice" style="margin:0 0 18px">${icon('file')}<span>อ้างอิง ${ClassicTemplates.get(project()).code} · สามารถกด “สร้างเล่ม 56 หน้า (Full PDF)” เพื่อรวมเล่มอ้างอิงและผลตรวจปัจจุบันได้ทันที หรือดูตัวอย่าง 5 หมวดหลักด้านล่าง</span></div><div class="builder"><div class="panel"><div class="editor-tabs"><button data-tab="content" class="${tab==='content'?'selected':''}">${icon('file')} เนื้อหารายงาน</button><button data-tab="photos" class="${tab==='photos'?'selected':''}">${icon('image')} รูปภาพ</button><button data-tab="settings" class="${tab==='settings'?'selected':''}">${icon('settings')} ตั้งค่า</button></div>${tab==='content'?`<div class="section-list"><div class="section-caption" style="padding:8px 10px 0">REPORT SECTIONS · ${project().sections.length} SECTIONS</div>${project().sections.map((s,i)=>`<div class="section-row ${section===s?'selected':''}" data-section="${s}" role="button" tabindex="0"><span class="section-num">0${i+1}</span><div><strong>${secLabels[s][0]}</strong><small>${secLabels[s][1]}</small></div>${s==='cover'?'<span class="badge green">พร้อมแก้ไข</span>':s==='performance'?'<span class="badge orange">รอข้อมูล</span>':''}</div>`).join('')}</div><div class="editor-section">${sectionEditor()}</div>`:tab==='photos'?`<div class="panel-body">${uploadZone()}<p class="source-note">เลือกภาพหลักได้จากคลังภาพ รูปต้นฉบับจะเก็บในเบราว์เซอร์เครื่องนี้</p><button data-view="photos">${icon('image')}เปิดคลังภาพ (${projectPhotos().length})</button></div>`:`<div class="panel-body">${field('code','เลขที่รายงาน',project().code)}<label class="field"><span>รูปแบบรายงาน</span><select data-field="template"><option value="PM-FP-001" ${project().template==='PM-FP-001'?'selected':''}>PM-FP-001 · Preventive Maintenance</option><option value="PT-FP-001" ${project().template==='PT-FP-001'?'selected':''}>PT-FP-001 · Performance Test</option></select></label><button data-view="designer">${icon('list')}จัดลำดับส่วนรายงาน</button></div>`}</div><div class="preview-shell"><div class="preview-toolbar"><span class="actions">${icon('eye')} Live Preview <span class="badge green" style="font-size:8px">LETTER</span></span><span class="actions"><button data-action="zoom-out" aria-label="ย่อ">−</button><span style="font-size:10px">${zoom}%</span><button data-action="zoom-in" aria-label="ขยาย">+</button><span class="divider" style="height:15px;margin:0 8px"></span><button data-action="print" aria-label="พิมพ์รายงาน">${icon('download')}</button></span></div><div class="preview-canvas" id="live-preview"><div style="width:${zoom}%;max-width:750px">${paper(section)}</div></div><div class="preview-bottom"><span style="width:5px;height:5px;background:#5d9c82;border-radius:50%"></span>อัปเดตตามข้อมูลที่บันทึก <span style="margin:0 8px">·</span> ${secLabels[section][0]} <span style="margin:0 8px">·</span> ฉบับร่าง</div></div></div>`}
function sectionEditor(){const p=project();switch(section){case'cover':return `<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:19px"><h3>รายละเอียดหน้าปก</h3><span class="badge">CoverBlock</span></div>${field('customer','ชื่อลูกค้า / บริษัท',p.customer)}${field('site','สถานที่ / สาขา',p.site)}<div class="form-grid">${field('code','เลขที่รายงาน',p.code)}${field('date','วันที่ตรวจสอบ',p.date,'date')}</div><label class="field"><span>รูปแบบปกตามต้นฉบับ</span><div class="field-inset">ปกใช้โลโก้ Pakorn และกราฟิกแดง–เทาจาก PDF เดิม ไม่มีภาพอุปกรณ์บนปก</div></label><div class="ai-card"><strong>${icon('spark')} Report Assistant</strong><p>สร้างร่างสรุปจากคำตอบและค่าที่บันทึกไว้ ให้คุณตรวจทานก่อนนำไปใช้</p><button data-action="draft">${icon('spark')}สร้างร่างจากข้อมูล</button></div><div class="notice">${icon('help')}ต้นแบบนี้บันทึกข้อมูลในเครื่อง และใช้ข้อความจากกฎที่กำหนด ยังไม่ได้เชื่อม AI หรือระบบผู้ใช้จริง</div>`;case'inspection':return `<h3>แบบตรวจสอบระบบ Fire Pump</h3><p class="source-note">ตรวจแล้ว ${M.questions.filter(([id])=>p.answers[id]?.value).length} / ${M.questions.length} รายการ คำตอบแต่ละข้อแสดงในตารางรายงานโดยตรง</p><button class="primary" data-view="checklist">${icon('list')}เปิดแบบตรวจสอบ</button>`;case'performance':return `<h3>Flow & Pressure Record</h3><p class="source-note">ค่าทดสอบที่กรอกจะแสดงในตารางและกราฟชุดเดียวกัน รายการที่ไม่ได้ทดสอบจะไม่แสดงเป็นศูนย์</p><button class="primary" data-view="tests">${icon('chart')}บันทึกผลทดสอบ</button>`;case'findings':return `<label class="field"><span>สรุปผลการตรวจสอบ</span><textarea class="summary-area" data-field="summary" ${locked()?'disabled':''}>${esc(p.summary)}</textarea><small>ร่างข้อความต้องได้รับการตรวจทานจากผู้รับผิดชอบ</small></label><button data-action="draft">${icon('spark')}สร้างร่างจากข้อมูล</button><label class="field" style="margin-top:18px"><span>ข้อเสนอแนะเพิ่มเติม</span><textarea data-field="notes" ${locked()?'disabled':''}>${esc(p.notes)}</textarea></label>`;case'appendix':return `<h3>หลักฐานประกอบรายงาน</h3><p class="source-note">รูปหลักฐาน ${projectPhotos().length} รูป · เอกสาร ${projectDocs().length} ไฟล์<br>ระบบแบ่งรูป 4 รูปต่อหน้าในฉบับพิมพ์</p><div class="actions"><button data-view="photos">${icon('image')}คลังภาพ</button><button data-view="documents">${icon('file')}เอกสารแนบ</button></div>`}}
function uploadZone(){return `<button class="upload-zone" data-action="upload" ${locked()?'disabled':''}>${icon('upload')}<strong>เพิ่มรูปภาพ หรือเลือกจากคลัง</strong><p>JPG, PNG, WebP · เลือกได้หลายรูป</p></button>`}
function paper(s,p=project(),photoSubset=null,pageNo=null,total=null){return ClassicTemplates.render({s,p,esc,questions:M.questions,photos:(photoSubset||photos.filter(a=>a.projectId===p.id)).filter(a=>!a.source),urls:photoUrls,pageNo,total,answerLabel,testTable,chart,formatDate})}

function answerLabel(v){return ({Y:'ปกติ',N:'ผิดปกติ',NONE:'ไม่มี / ไม่เกี่ยวข้อง',NOT_TESTED:'ไม่ได้ตรวจ'})[v]||'ยังไม่ตรวจ'}
function testTable(p){return `<table><thead><tr><th>จุดทดสอบ</th><th>Flow (GPM)</th><th>Discharge (PSI)</th><th>Suction (PSI)</th><th>สถานะ</th></tr></thead><tbody>${p.tests.map(t=>`<tr><td>${t.point}%</td><td>${t.status==='TESTED'?esc(t.flow??'—'):'—'}</td><td>${t.status==='TESTED'?esc(t.discharge??'—'):'—'}</td><td>${t.status==='TESTED'?esc(t.suction??'—'):'—'}</td><td>${testStatus(t.status)}</td></tr>`).join('')}</tbody></table>`}
function testStatus(s){return ({PENDING:'รอบันทึก',TESTED:'ทดสอบแล้ว',NOT_TESTED:'ไม่ได้ทดสอบ'})[s]||'รอตรวจทาน'}
function chart(p=project()){const data=p.tests.filter(t=>t.status==='TESTED'&&t.flow!==null&&t.discharge!==null&&Number.isFinite(Number(t.flow))&&Number.isFinite(Number(t.discharge)));const maxX=Math.max(100,p.ratedFlow*1.5,...data.map(t=>Number(t.flow))),minY=Math.min(0,...data.map(t=>Number(t.discharge))),maxY=Math.max(100,...data.map(t=>Number(t.discharge)))*1.15;const x=t=>55+Number(t.flow)/maxX*410,y=t=>205-(Number(t.discharge)-minY)/(maxY-minY)*165;let series='';for(let i=1;i<p.tests.length;i++){let a=p.tests[i-1],b=p.tests[i];if(data.includes(a)&&data.includes(b))series+=`<line x1="${x(a)}" y1="${y(a)}" x2="${x(b)}" y2="${y(b)}" stroke="#447fb5" stroke-width="2.5"/>`}return `<svg class="chart" role="img" aria-label="กราฟแรงดันด้านส่งตามอัตราการไหลจริง หน่วย PSI และ GPM" viewBox="0 0 500 250"><text x="25" y="20">PSI · Discharge pressure</text>${[0,1,2,3,4].map(i=>`<line x1="55" y1="${205-i*41.25}" x2="465" y2="${205-i*41.25}" stroke="#e7edf3"/><text x="42" y="${209-i*41.25}" text-anchor="end">${Math.round(minY+(maxY-minY)*i/4)}</text><text x="${55+i*102.5}" y="225" text-anchor="middle">${Math.round(maxX*i/4)}</text>`).join('')}<text x="465" y="246" text-anchor="end">Actual Flow · GPM</text>${series}${data.map(t=>`<circle cx="${x(t)}" cy="${y(t)}" r="4" fill="#367ab6"/><text x="${x(t)}" y="${y(t)-12}" text-anchor="middle">${t.point}%</text>`).join('')}${!data.length?'<text x="260" y="120" text-anchor="middle">ยังไม่มีค่าทดสอบที่บันทึกครบ</text>':''}</svg>`}
function dashboard(){return heading('ภาพรวมการทำงาน','ยินดีต้อนรับกลับมา ดูความคืบหน้าของทีมและรายงานในที่เดียว',`<button class="primary" data-action="new-project">${icon('plus')}สร้างโครงการ</button>`)+`<div class="stats">${[[state.projects.length,'โครงการทั้งหมด','folder'],[state.projects.filter(p=>p.status==='DRAFT').length,'กำลังจัดทำรายงาน','file'],[state.projects.filter(p=>p.status==='SUBMITTED').length,'รอตรวจทาน','clock'],[state.projects.filter(p=>p.status==='APPROVED').length,'ล็อกฉบับตรวจทาน','shield']].map(([n,l,i])=>`<div class="stat"><div>${l}${icon(i)}</div><strong>${n}</strong><small>ข้อมูลในเบราว์เซอร์เครื่องนี้</small></div>`).join('')}</div><div class="panel"><div class="panel-head"><h2>โครงการล่าสุด</h2><button class="ghost" data-view="projects">ดูทั้งหมด ${icon('arrow')}</button></div>${projectTable()}</div><div class="cards" style="margin-top:22px"><div class="panel panel-body"><span class="badge blue">01 · FIELD</span><h3 style="margin-top:16px">บันทึกหน้างาน</h3><p class="source-note">ตอบแบบตรวจสอบและบันทึกค่าจากเครื่องมือ</p><button data-view="checklist">เริ่มตรวจสอบ ${icon('arrow')}</button></div><div class="panel panel-body"><span class="badge green">02 · STUDIO</span><h3 style="margin-top:16px">รูปภาพพร้อม รายงานพร้อม</h3><p class="source-note">นำเข้ารูปและจัดทำรายงานพร้อมพรีวิวสด</p><button data-view="builder">เปิด Report Builder ${icon('arrow')}</button></div><div class="panel panel-body"><span class="badge orange">03 · REVIEW</span><h3 style="margin-top:16px">ตรวจทานก่อนส่งออก</h3><p class="source-note">ตรวจข้อมูลที่ขาดและหลักฐานก่อนส่งเล่ม</p><button data-view="inbox">ตรวจความครบถ้วน ${icon('arrow')}</button></div></div>`}
function projectTable(){const list=state.projects.filter(p=>(p.customer+p.code+p.site).toLowerCase().includes(search.toLowerCase()));return `<div class="table-wrap"><table><thead><tr><th>โครงการ / ลูกค้า</th><th>ประเภทงาน</th><th>วันที่ตรวจ</th><th>ความคืบหน้า</th><th>สถานะ</th><th></th></tr></thead><tbody>${list.map(p=>`<tr><td><strong>${esc(p.code)}</strong><small>${esc(p.customer)} · ${esc(p.site)}</small></td><td>${p.template==='PM-FP-001'?'Preventive Maintenance':'Performance Test'}</td><td>${formatDate(p.date)}</td><td style="min-width:110px"><small>${completion(p)}%</small><div class="progress"><i style="width:${completion(p)}%"></i></div></td><td>${badge(p)}</td><td><button data-open="${p.id}" aria-label="เปิด ${esc(p.code)}">${icon('arrow')}</button></td></tr>`).join('')||'<tr><td colspan="6">ไม่พบโครงการ</td></tr>'}</tbody></table></div>`}
function projectsView(){const p=project();return heading('โครงการทั้งหมด','จัดการข้อมูลลูกค้า สถานที่ และรายละเอียดงานตรวจสอบ',`<button data-action="clone">${icon('copy')}สร้างจากงานเดิม</button><button class="primary" data-action="new-project">${icon('plus')}สร้างโครงการ</button>`)+`<div class="panel"><div class="table-tools"><input class="input" id="project-search" placeholder="ค้นหาโครงการ ลูกค้า หรือเลขที่รายงาน" value="${esc(search)}"></div><div id="project-table">${projectTable()}</div></div><div class="panel" style="margin-top:24px"><div class="panel-head"><h2>ข้อมูลโครงการที่เลือก · ${esc(p.code)}</h2>${badge()}</div><div class="panel-body"><div class="form-grid">${field('customer','ชื่อลูกค้า',p.customer)}${field('site','สถานที่ / สาขา',p.site)}${field('code','เลขที่รายงาน',p.code)}${field('date','วันที่ตรวจสอบ',p.date,'date')}${field('engine','ชื่ออุปกรณ์',p.engine)}${field('serial','Serial Number',p.serial)}</div><div class="actions"><button data-view="assets">${icon('settings')}ข้อมูลอุปกรณ์</button><button class="primary" data-view="builder">เปิด Report Builder ${icon('arrow')}</button></div></div></div>`}
function assetsView(){const p=project();return heading('Customer & Asset 360','ข้อมูลประจำอุปกรณ์สำหรับนำไปใช้ในรายงานและงานตรวจครั้งต่อไป')+projectStrip()+`<div class="panel"><div class="panel-head"><h2>ข้อมูลอุปกรณ์</h2><span class="badge blue">ASSET MASTER</span></div><div class="panel-body"><div class="form-grid">${field('customer','ลูกค้า',p.customer)}${field('site','สถานที่',p.site)}${field('engine','ประเภท / รุ่นอุปกรณ์',p.engine)}${field('serial','Serial Number',p.serial)}${field('ratedFlow','Rated Flow (GPM)',p.ratedFlow,'number','min="0" step="any"')}${field('ratedPressure','Rated Pressure (PSI)',p.ratedPressure,'number','min="0" step="any"')}</div><p class="notice">${icon('warning')}ข้อมูล Rated Pressure ต้องตรวจจาก Nameplate หรือเอกสารอ้างอิงที่ยืนยันแล้ว ต้นแบบยังไม่ใช้ข้อมูลนี้ตัดสินผลมาตรฐาน</p><button data-action="clone">${icon('copy')}สร้างงานครั้งใหม่จากอุปกรณ์นี้</button></div></div>`}
function templatesView(){return heading('Template Library','รูปแบบรายงานมาตรฐาน ออกแบบครั้งเดียว ใช้ซ้ำได้ทุกโครงการ',`<button data-view="designer">${icon('settings')}จัดโครงสร้างรายงาน</button>`)+`<div class="cards">${[['PM-FP-001','Fire Pump','Preventive Maintenance','รายงานบำรุงรักษาเชิงป้องกัน แบบตรวจสอบ ผลทดสอบ และรูปหลักฐาน'],['PT-FP-001','Fire Pump','Performance Test','รายงานทดสอบสมรรถนะ ตาราง Flow & Pressure และกราฟจากผลวัดจริง']].map(([code,title,type,desc])=>`<div class="panel template-card"><div class="template-art classic-template-art"><img src="assets/templates/${code==='PM-FP-001'?'pm151':'pt095'}/original-cover.png" alt="ปก PDF ต้นฉบับ ${code}"></div><span class="badge blue">${code} · v0.1</span><h2 style="margin-top:15px">${title}</h2><h3 style="font-weight:500;margin-top:4px">${type}</h3><p>${desc}</p><button class="primary" data-template="${code}">ใช้เทมเพลตนี้ ${icon('arrow')}</button></div>`).join('')}</div><p class="source-note">ต้นแบบใช้โครงสร้างรายงานที่กำหนดไว้ล่วงหน้า การแก้ Field Binding และเงื่อนไขของ Template อยู่ใน MVP Specification</p>`}
function worklist(){return heading('งานของช่างเทคนิค','บันทึกผลตรวจ เพิ่มรูป และส่งข้อมูลให้สำนักงานตรวจทาน',`<button data-view="projects">${icon('folder')}ดูโครงการทั้งหมด</button>`)+projectStrip()+`<div class="cards">${[['checklist','list','01','แบบตรวจสอบ',`${M.questions.filter(([id])=>project().answers[id]?.value).length} / ${M.questions.length} รายการ`],['photos','image','02','รูปภาพหลักฐาน',`${projectPhotos().length} รูปในโครงการ`],['tests','chart','03','ค่าทดสอบสมรรถนะ',`${project().tests.filter(t=>t.status!=='PENDING').length} / 3 จุดทดสอบ`],['documents','file','04','เอกสารและใบสอบเทียบ',`${projectDocs().length} เอกสาร`]].map(([v,i,n,t,d])=>`<div class="panel panel-body"><span class="badge blue">${n}</span><div style="margin:20px 0;color:var(--blue)">${icon(i)}</div><h2>${t}</h2><p class="source-note">${d}</p><button class="primary" data-view="${v}">เปิดบันทึกข้อมูล ${icon('arrow')}</button></div>`).join('')}</div><div class="notice">${icon('help')}ข้อมูลฟอร์มบันทึกในเครื่องอัตโนมัติ รูปเก็บใน IndexedDB ของเบราว์เซอร์ ยังไม่มีการซิงก์กับสำนักงานหรืออุปกรณ์เครื่องอื่น</div>`}
function checklist(){return heading('แบบตรวจสอบหน้างาน','เลือกผลตรวจตามสภาพจริง และระบุรายละเอียดเมื่อพบความผิดปกติ',`<button data-view="worklist">กลับไปงานของฉัน</button><button class="primary" data-view="builder">${icon('eye')}ดูในรายงาน</button>`)+projectStrip()+`<div class="two-cols"><div class="panel"><div class="panel-head"><h2>Fire Pump Inspection</h2><span class="badge blue">${completion()}% บันทึกแล้ว</span></div><div class="panel-body">${M.questions.map(([id,label,group],i)=>{const a=project().answers[id]||{};return `<div class="check-row"><div class="check-title"><strong>${i+1}. ${label}</strong><small>${group}</small></div><div class="choices">${[['Y','ปกติ'],['N','ผิดปกติ'],['NONE','ไม่เกี่ยวข้อง'],['NOT_TESTED','ไม่ได้ตรวจ']].map(([v,t])=>`<button data-answer="${id}" data-value="${v}" class="${a.value===v?'chosen':''} ${v==='N'?'no':''}" ${locked()?'disabled':''}>${v==='Y'?icon('check'):''}${t}</button>`).join('')}</div><textarea class="input" data-remark="${id}" placeholder="${a.value==='N'?'ระบุข้อบกพร่อง (จำเป็น)':'หมายเหตุ / ข้อสังเกต'}" ${locked()?'disabled':''}>${esc(a.remark||'')}</textarea></div>`}).join('')}</div></div><div><div class="panel panel-body"><h2>หลักฐานจากหน้างาน</h2><p class="source-note">เพิ่มรูปก่อนหรือหลังการตรวจได้ รูปทุกรูปผูกกับโครงการที่เลือก</p>${uploadZone()}<button style="margin-top:15px" data-view="photos">${icon('image')}ดูรูปในโครงการ (${projectPhotos().length})</button></div><div class="notice">${icon('warning')}ไม่มีการตั้งค่าเริ่มต้นเป็น “ปกติ” ให้เลือกรายการที่ตรวจจริงเท่านั้น</div></div></div>`}
function photosView(){return heading('คลังภาพโครงการ','รวบรวมหลักฐาน จัดหมวด และเลือกภาพสำหรับรายงาน',`<button class="primary" data-action="upload" ${locked()?'disabled':''}>${icon('plus')}เพิ่มรูปภาพ</button>`)+projectStrip()+`<div class="panel panel-body"><div class="actions" style="justify-content:space-between"><h2>ภาพทั้งหมด <span class="badge">${projectPhotos().length} รูป</span></h2><span class="subtle">เลือกหมวดและคำบรรยายได้ด้วยตนเอง</span></div>${projectPhotos().length?`<div class="photo-grid">${projectPhotos().map(a=>`<div class="photo-card"><img src="${photoUrls.get(a.id)}" alt="${esc(a.caption||a.name)}"><div class="photo-info"><select class="input" data-photo-category="${a.id}" ${locked()?'disabled':''}>${categories.map(c=>`<option ${a.category===c?'selected':''}>${c}</option>`).join('')}</select><input class="input" data-photo-caption="${a.id}" value="${esc(a.caption)}" placeholder="คำบรรยายภาพ" ${locked()?'disabled':''}><div class="actions"><button data-cover="${a.id}" ${locked()?'disabled':''}>${a.id===project().cover?icon('check'):icon('image')}${a.id===project().cover?'ภาพหน้าปก':'ใช้เป็นหน้าปก'}</button><button class="ghost" data-delete-photo="${a.id}" aria-label="ลบภาพ ${esc(a.name)}" ${locked()?'disabled':''}>${icon('trash')}</button></div><small>${esc(a.name)}</small></div></div>`).join('')}</div>`:`<div class="empty-state">${icon('image')}<h3>เริ่มจากภาพที่คุณถ่ายไว้</h3><p>เพิ่มภาพหลายรูปพร้อมกัน แล้วจัดหมวดให้ตรงกับหัวข้อรายงาน</p><button class="primary" data-action="upload">${icon('upload')}เลือกภาพจากเครื่อง</button></div>`}</div><p class="source-note">ภาพต้นฉบับเก็บในเครื่อง ไม่ได้ส่งไปวิเคราะห์ AI หรืออัปโหลดไปเซิร์ฟเวอร์ · สูงสุด 15 MB ต่อภาพ</p>`}
function testsView(){return heading('ผลทดสอบสมรรถนะ','บันทึกค่าที่วัดจริง ตารางและกราฟใช้ข้อมูลชุดเดียวกัน',`<button data-view="assets">${icon('settings')}ข้อมูล Nameplate</button><button class="primary" data-view="builder">${icon('eye')}ดูในรายงาน</button>`)+projectStrip()+`<div class="panel"><div class="panel-head"><h2>Flow & Pressure Test</h2><span class="badge orange">รอประเมินทางวิศวกรรม</span></div><div class="panel-body"><div class="table-wrap"><table class="test-table"><thead><tr><th>จุดทดสอบ</th><th>สถานะ</th><th>Actual Flow · GPM</th><th>Discharge · PSI</th><th>Suction · PSI</th><th>เหตุผล / หมายเหตุ</th></tr></thead><tbody>${project().tests.map((t,i)=>`<tr><td><strong>${t.point}%</strong></td><td><select class="input" data-test="${i}" data-metric="status" ${locked()?'disabled':''}>${[['PENDING','รอบันทึก'],['TESTED','ทดสอบแล้ว'],['NOT_TESTED','ไม่ได้ทดสอบ']].map(([v,s])=>`<option value="${v}" ${v===t.status?'selected':''}>${s}</option>`).join('')}</select></td>${['flow','discharge','suction'].map(k=>`<td><input class="test-input" type="number" step="any" ${k==='flow'?'min="0"':''} data-test="${i}" data-metric="${k}" value="${esc(t[k])}" ${t.status!=='TESTED'||locked()?'disabled':''} aria-label="${k} ที่ ${t.point}%"></td>`).join('')}<td><input class="input" data-test="${i}" data-metric="reason" value="${esc(t.reason||'')}" placeholder="${t.status==='NOT_TESTED'?'ระบุเหตุผล (จำเป็น)':'หมายเหตุ'}" ${locked()?'disabled':''}></td></tr>`).join('')}</tbody></table></div><div id="chart-area">${chart()}</div><div class="notice">${icon('help')}กราฟใช้ Actual Flow (GPM) บนแกน X และ Discharge (PSI) บนแกน Y จุดที่ไม่ได้ทดสอบจะไม่ถูกวาด และไม่ลากเส้นข้ามข้อมูลที่ขาด ต้นแบบยังไม่ประเมิน Pass / Fail ตามมาตรฐาน</div></div></div>`}
function documentsView(){return heading('เอกสารและใบสอบเทียบ','เก็บเอกสารต้นฉบับและวันหมดอายุสำหรับตรวจทาน',`<button class="primary" data-action="upload-doc" ${locked()?'disabled':''}>${icon('upload')}เพิ่มเอกสาร</button>`)+projectStrip()+`<div class="panel"><div class="panel-head"><h2>เอกสารในโครงการ</h2><span class="badge">${projectDocs().length} ไฟล์</span></div>${projectDocs().length?`<table><thead><tr><th>ชื่อเอกสาร</th><th>วันหมดอายุที่ระบุ</th><th>สถานะ</th><th></th></tr></thead><tbody>${projectDocs().map(d=>`<tr><td>${esc(d.name)}</td><td><input class="input" type="date" data-doc-expiry="${d.id}" value="${esc(d.expiry||'')}" ${locked()?'disabled':''}></td><td><span class="badge ${d.expiry&&d.expiry<project().date?'orange':''}">${d.expiry?(d.expiry<project().date?'หมดอายุก่อนวันตรวจ':'รอตรวจสอบต้นฉบับ'):'ยังไม่ระบุวันหมดอายุ'}</span></td><td><button data-download-doc="${d.id}">${icon('download')}เปิดต้นฉบับ</button><button class="ghost" data-delete-doc="${d.id}" aria-label="ลบเอกสาร" ${locked()?'disabled':''}>${icon('trash')}</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty-state">${icon('file')}<h3>ยังไม่มีเอกสารประกอบ</h3><p>เพิ่ม PDF ใบ Calibration หรือเอกสารที่เกี่ยวข้องกับการตรวจ</p><button data-action="upload-doc">${icon('plus')}เพิ่มเอกสาร</button></div>`}</div><p class="source-note">เอกสารเก็บในเครื่อง ต้นแบบแสดงรายการแนบในรายงาน แต่ยังไม่ได้รวมหน้า PDF ต้นฉบับเข้าเล่ม</p>`}
function qaView(){const issues=M.validate(project(),projectPhotos());return heading(view==='review'?'Engineering Review':'ตรวจความครบถ้วน','เปิดดูรายการที่ยังขาด และตรวจหลักฐานก่อนส่งรายงาน',`<button data-view="documents">${icon('file')}เอกสารแนบ</button><button class="primary" data-view="approval">ไปหน้าตรวจทาน ${icon('arrow')}</button>`)+projectStrip()+`<div class="two-cols"><div class="panel"><div class="panel-head"><h2>รายการที่ต้องตรวจสอบ</h2><span class="badge ${issues.length?'orange':'green'}">${issues.length} รายการ</span></div><div class="panel-body">${issues.map(i=>`<div class="issue">${icon('warning')}<span>${esc(i.text)}</span><button data-view="${i.view}">ไปแก้ไข ${icon('arrow')}</button></div>`).join('')||`<div class="empty-state">${icon('check')}<h3>ข้อมูลสำหรับต้นแบบครบแล้ว</h3><p>ยังต้องตรวจความถูกต้องของหลักฐานและผลทางวิศวกรรมก่อนรับรองจริง</p></div>`}</div></div><div><div class="panel panel-body"><h2>ผลทดสอบที่บันทึก</h2><div class="table-wrap" style="margin-top:18px">${testTable(project())}</div>${chart()}<span class="badge orange">ยังไม่มี Rule Set ที่วิศวกรรับรอง</span><p class="source-note">ไม่มีการคำนวณเกณฑ์มาตรฐานหรือให้ผลผ่านอัตโนมัติ</p></div><div class="notice">${icon('shield')}รายงานสองโครงการที่ตั้งไว้เป็นข้อมูลเริ่มต้น ค่าตรวจทั้งหมดรอผู้ใช้กรอก ไม่ได้นำผลตรวจปีเดิมมาใช้เป็นผลตรวจใหม่</div></div></div>`}
function approvalView(){const p=project(),issues=M.validate(p,projectPhotos());return heading('ตรวจทานและส่งออก','ตรวจความครบถ้วน ล็อกสำเนาข้อมูล และส่งออกฉบับร่าง',`${badge()}<button data-action="assemble-pdf" class="primary" style="background:#0d7a5f">${icon('spark')}สร้างเล่ม 56 หน้า (Full PDF)</button><button data-action="print" class="primary">${icon('download')}ส่งออก PDF</button>`)+projectStrip()+`<div class="two-cols"><div class="panel"><div class="panel-head"><h2>Review workflow · ต้นแบบ</h2><span class="badge">Revision ${p.revision}</span></div><div class="panel-body"><div class="field-inset">${icon('file')} ร่างรายงาน → ส่งตรวจทาน → ล็อก Snapshot</div><div class="field-inset" style="margin-top:14px"><strong style="display:block;margin-bottom:8px">ข้อมูลวิศวกรผู้ตรวจทานและลงนาม</strong><label class="field"><span>ชื่อ-นามสกุล วิศวกร</span><input data-field="engineer_name" value="${esc(p.engineer_name||'')}" placeholder="เช่น นาย ชูชาติ ใคร้มา" ${locked()?'disabled':''}></label><label class="field"><span>เลขที่ใบอนุญาต กว.</span><input data-field="engineer_license" value="${esc(p.engineer_license||'')}" placeholder="เช่น ภย. XXXXX" ${locked()?'disabled':''}></label><div class="actions" style="margin-top:8px"><button data-action="upload-signature" ${locked()?'disabled':''}>${icon('image')}${p.engineer_signature_data?'เปลี่ยนภาพลายเซ็น':'แนบภาพลายเซ็น'}</button>${p.engineer_signature_data?`<span class="badge green">มีลายเซ็นแล้ว</span><button class="ghost" data-action="remove-signature" ${locked()?'disabled':''}>${icon('trash')}ลบลายเซ็น</button>`:''}</div></div><p class="source-note" style="margin-top:10px">การดำเนินการที่หน้านี้เป็นการทดลองขั้นตอนภายในเครื่อง ไม่มีการลงนามหรือรับรองโดยวิศวกรจริง</p><label class="field"><span>หมายเหตุการตรวจทาน</span><textarea id="review-note" placeholder="ระบุสิ่งที่ต้องแก้ไข หรือเหตุผลการตรวจทาน"></textarea></label><div class="actions">${!locked()?`<button class="primary" data-action="submit">${icon('arrow')}ส่งตรวจทาน (ทดลอง)</button>`:p.status==='SUBMITTED'?`<button data-action="return">ส่งกลับแก้ไข</button><button class="primary" data-action="approve">${icon('shield')}ล็อกฉบับตรวจทาน (ทดลอง)</button>`:`<button data-action="revision">${icon('copy')}สร้าง Revision ใหม่</button>`}</div><div class="notice">${icon('warning')}${issues.length?`มีข้อมูลที่ยังไม่ครบ ${issues.length} รายการ ต้องแก้ให้ครบก่อนส่งตรวจ`:'ข้อมูลตามแบบฟอร์มครบแล้ว กรุณาตรวจทานความถูกต้องก่อนดำเนินการ'}</div><button style="margin-top:14px" data-view="inbox">เปิดรายการตรวจความครบถ้วน</button></div></div><div class="panel"><div class="panel-head"><h2>Snapshot ที่บันทึก</h2><span class="badge">${p.snapshots.length} ฉบับ</span></div><div class="panel-body">${p.snapshots.map((s,i)=>`<div class="audit-item"><strong>Snapshot #${i+1} · Revision ${s.revision}</strong><small>${new Date(s.at).toLocaleString('th-TH')} · ${esc(s.note||'ไม่มีหมายเหตุ')}</small><button style="margin-top:8px" data-snapshot="${i}">${icon('download')}ดาวน์โหลดข้อมูล JSON</button></div>`).join('')||'<p class="source-note">ยังไม่มี Snapshot ระบบจะบันทึกสำเนาข้อมูลเมื่อทดลองล็อกฉบับตรวจทาน</p>'}</div></div></div>`}
function designer(){return heading('โครงสร้างเทมเพลตรายงาน','เลือกส่วนที่แสดงและจัดลำดับหน้าสำหรับโครงการนี้',`<button class="primary" data-view="builder">${icon('eye')}ดู Live Preview</button>`)+projectStrip()+`<div class="two-cols"><div class="panel panel-body"><h2 style="margin-bottom:20px">Report sections</h2>${project().sections.map((s,i)=>`<div class="designer-block"><span class="badge">${i+1}</span><div><h3>${secLabels[s][0]}</h3><p class="subtle">${secLabels[s][1]}</p></div><div class="actions"><button data-move="${s}" data-direction="-1" ${i===0||locked()?'disabled':''} aria-label="เลื่อนขึ้น">↑</button><button data-move="${s}" data-direction="1" ${i===project().sections.length-1||locked()?'disabled':''} aria-label="เลื่อนลง">↓</button></div></div>`).join('')}</div><div class="panel panel-body"><h2>Modular template</h2><p class="source-note">CoverBlock · ChecklistBlock · TestDataBlock · ChartBlock · FindingBlock · ImageGridBlock</p><div class="notice">${icon('help')}ต้นแบบปรับลำดับส่วนได้ การลากวาง Component, Field Binding และเงื่อนไขการแสดงผลจะพัฒนาต่อในระบบจริง</div></div></div>`}
function settingsView(){return heading('ตั้งค่าและประวัติ','จัดการข้อมูลในเครื่อง และดูประวัติการแก้ไขโครงการ',`<button data-action="import-package">${icon('folder')}นำเข้าแพ็กเกจ (+รูปภาพ)</button><button data-action="export-package" class="primary">${icon('upload')}ส่งออกแพ็กเกจ (+รูปภาพ)</button><button data-action="backup">${icon('download')}สำรอง JSON</button>`)+`<div class="two-cols"><div class="panel"><div class="panel-head"><h2>ประวัติการแก้ไข · ${esc(project().code)}</h2><span class="badge">LOCAL LOG</span></div><div class="panel-body">${project().history.slice(0,40).map(h=>`<div class="audit-item">${esc(h.action)}<small>${new Date(h.at).toLocaleString('th-TH')} · ${esc(h.actor)}</small></div>`).join('')||'<p class="source-note">ยังไม่มีประวัติการเปลี่ยนแปลง</p>'}</div></div><div class="panel panel-body"><h2>Prototype capabilities</h2><p class="source-note">✓ ฟอร์มตรวจสอบและกราฟจากค่าจริง<br>✓ คลังภาพและเอกสารใน IndexedDB<br>✓ พรีวิว Letter และพิมพ์ / บันทึก PDF<br>✓ สร้างเล่มสมบูรณ์ 56 หน้าด้วย PDF-Lib<br>✓ ส่งออก/นำเข้าแพ็กเกจงานพร้อมรูปถ่ายทั้งหมด<br>✓ ทดลอง Review และบันทึก Snapshot<br><br>ระบบผู้ใช้และสิทธิ์, AI Vision/OCR, การซิงก์ข้อมูลอัตโนมัติ และ DOCX อยู่ในแผนพัฒนา</p><div class="notice">${icon('help')}ใช้ปุ่ม “ส่งออกแพ็กเกจ (+รูปภาพ)” เพื่อส่งไฟล์โครงการรวมรูปภาพทั้งหมดให้ช่าง/ออฟฟิศนำเข้าต่อได้ทันทีโดยรูปไม่ตกหล่น</div></div></div>`}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal()}
function closeModal(){$('#modal').close();$('#modal').classList.remove('wide-modal')}
function projectModal(template='PM-FP-001'){modal(`<h2>สร้างโครงการใหม่</h2><p>เริ่มรายงานจากเทมเพลตมาตรฐาน พร้อมแบบตรวจสอบเปล่า</p><form id="new-project-form"><label class="field"><span>ชื่อลูกค้า</span><input name="customer" required placeholder="บริษัท / หน่วยงาน"></label><label class="field"><span>สถานที่ / สาขา</span><input name="site" required></label><div class="form-grid"><label class="field"><span>เลขที่รายงาน</span><input name="code" required placeholder="PM.FP.69-XXX"></label><label class="field"><span>วันที่ตรวจ</span><input name="date" type="date" required value="${new Date().toISOString().slice(0,10)}"></label></div><label class="field"><span>เทมเพลต</span><select name="template"><option value="PM-FP-001" ${template==='PM-FP-001'?'selected':''}>Preventive Maintenance</option><option value="PT-FP-001" ${template==='PT-FP-001'?'selected':''}>Performance Test</option></select></label><div class="actions"><button type="button" data-action="close-modal">ยกเลิก</button><button type="submit" class="primary">สร้างโครงการ ${icon('arrow')}</button></div></form>`)}
function refreshPreview(){if(view==='builder'){$('#live-preview').innerHTML=`<div style="width:${zoom}%;max-width:750px">${paper(section)}</div>`}}
function downloadJSON(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));downloadURL(url,name);setTimeout(()=>URL.revokeObjectURL(url),5000)}
function downloadURL(url,name){const a=document.createElement('a');a.href=url;a.download=name;a.click()}
const _b64={toBase64:b=>new Promise((res,rej)=>{if(typeof FileReader!=='undefined'){const r=new FileReader();r.onloadend=()=>res(r.result);r.onerror=rej;r.readAsDataURL(b)}else b.arrayBuffer().then(buf=>res('data:'+(b.type||'image/png')+';base64,'+Buffer.from(buf).toString('base64'))).catch(rej)}),toBlob:d=>{const p=d.split(','),m=p[0].match(/:(.*?);/)?.[1]||'image/png',b=(typeof atob!=='undefined'?atob:(s=>Buffer.from(s,'base64').toString('binary')))(p[1]);let n=b.length,u=new Uint8Array(n);while(n--)u[n]=b.charCodeAt(n);return new Blob([u],{type:m})}};
async function exportPackage(){const p=project();toast('กำลังรวมไฟล์รูปภาพและข้อมูลโครงการ...');try{const currentPhotos=projectPhotos().filter(a=>!a.source),packedPhotos=[];for(const ph of currentPhotos){let dataUrl='';if(ph.blob){try{dataUrl=await _b64.toBase64(ph.blob)}catch(e){console.error(e)}}packedPhotos.push({id:ph.id,projectId:ph.projectId,name:ph.name,caption:ph.caption,category:ph.category,hash:ph.hash,at:ph.at,dataUrl})}const currentDocs=projectDocs(),packedDocs=[];for(const doc of currentDocs){let dataUrl='';if(doc.blob){try{dataUrl=await _b64.toBase64(doc.blob)}catch(e){console.error(e)}}packedDocs.push({id:doc.id,projectId:doc.projectId,name:doc.name,expiry:doc.expiry,at:doc.at,dataUrl})}const payload={version:1,type:'idc-full-package',exportedAt:new Date().toISOString(),project:p,photos:packedPhotos,documents:packedDocs};downloadJSON(payload,`${p.code}-complete-package.json`);toast(`ส่งออกแพ็กเกจเรียบร้อย (รวมภาพ ${packedPhotos.length} รูป)`)}catch(err){console.error(err);toast('ส่งออกแพ็กเกจไม่สำเร็จ: '+err.message)}}
async function importPackage(file){if(!file)return;toast('กำลังนำเข้าแพ็กเกจโครงการ...');try{const text=await file.text(),pkg=JSON.parse(text);if(!pkg.project)throw new Error('ไฟล์ไม่ถูกต้อง ไม่พบข้อมูลโครงการ');const incomingProject=pkg.project,idx=state.projects.findIndex(p=>p.id===incomingProject.id||p.code===incomingProject.code);if(idx>=0)state.projects[idx]=incomingProject;else state.projects.push(incomingProject);state.active=incomingProject.id;let imgCount=0;if(Array.isArray(pkg.photos)){for(const ph of pkg.photos){if(!ph.dataUrl)continue;const blob=_b64.toBlob(ph.dataUrl),item={id:ph.id,projectId:incomingProject.id,name:ph.name,caption:ph.caption||'',category:ph.category||categories[0],hash:ph.hash,at:ph.at||new Date().toISOString(),blob};await dbWrite('media',item);const ex=photos.findIndex(x=>x.id===item.id);if(ex>=0)photos[ex]=item;else photos.push(item);photoUrls.set(item.id,URL.createObjectURL(blob));imgCount++}}if(Array.isArray(pkg.documents)){for(const doc of pkg.documents){if(!doc.dataUrl)continue;const blob=_b64.toBlob(doc.dataUrl),item={id:doc.id,projectId:incomingProject.id,name:doc.name,expiry:doc.expiry||'',at:doc.at||new Date().toISOString(),blob};await dbWrite('documents',item);const ex=documents.findIndex(x=>x.id===item.id);if(ex>=0)documents[ex]=item;else documents.push(item)}}persist(`นำเข้าแพ็กเกจโครงการ ${incomingProject.code}`);render();toast(`นำเข้าโครงการสำเร็จ! (รูปภาพ ${imgCount} รูป)`)}catch(err){console.error(err);toast('นำเข้าไม่สำเร็จ: '+err.message)}}
async function assembleFullPDF(){const p=project();toast('กำลังประกอบเล่ม 56 หน้าจากเทมเพลตต้นฉบับ...');try{if(typeof PDFLib==='undefined')throw new Error('กำลังโหลด PDFLib กรุณาลองใหม่อีกครั้ง');const m=ClassicTemplates.get(p),pdfUrl=`assets/templates/${m.key}/reference.pdf`,res=await fetch(pdfUrl);if(!res.ok)throw new Error('ไม่สามารถโหลดเทมเพลตต้นฉบับได้');const pdfBytes=await res.arrayBuffer(),pdfDoc=await PDFLib.PDFDocument.load(pdfBytes);let customFont=null;try{if(typeof fontkit!=='undefined'){pdfDoc.registerFontkit(fontkit);const fRes=await fetch('assets/Sarabun-Regular.ttf');if(fRes.ok){const fontBytes=await fRes.arrayBuffer();customFont=await pdfDoc.embedFont(fontBytes)}}}catch(e){console.warn(e)}const fallbackFont=await pdfDoc.embedFont(PDFLib.StandardFonts.HelveticaBold),activeFont=customFont||fallbackFont;const company=p.report_customer_line||`${p.customer}${p.site?' ('+p.site+')':''}`,code=p.code||m.code,dateStr=p.date?new Date(p.date).toLocaleDateString('th-TH',{year:'numeric',month:'long',day:'numeric'}):'';const page1=pdfDoc.getPage(0),p1s=page1.getSize();page1.drawRectangle({x:68,y:p1s.height-245,width:440,height:35,color:PDFLib.rgb(1,1,1)});page1.drawText(company,{x:71,y:p1s.height-235,size:14,font:activeFont,color:PDFLib.rgb(0,0,0)});page1.drawRectangle({x:500,y:20,width:95,height:25,color:PDFLib.rgb(1,1,1)});page1.drawText(code,{x:515,y:26,size:10,font:fallbackFont,color:PDFLib.rgb(0.3,0.3,0.3)});if(pdfDoc.getPageCount()>1){const page2=pdfDoc.getPage(1),p2s=page2.getSize();page2.drawRectangle({x:330,y:p2s.height-48,width:260,height:20,color:PDFLib.rgb(1,1,1)});page2.drawText(company,{x:340,y:p2s.height-42,size:9,font:activeFont,color:PDFLib.rgb(0,0,0)});page2.drawRectangle({x:120,y:p2s.height-155,width:400,height:30,color:PDFLib.rgb(1,1,1)});page2.drawText(company,{x:140,y:p2s.height-146,size:14,font:activeFont,color:PDFLib.rgb(0,0,0)});if(dateStr){page2.drawRectangle({x:190,y:p2s.height-590,width:240,height:25,color:PDFLib.rgb(1,1,1)});page2.drawText(`วันที่ทดสอบ ${dateStr}`,{x:205,y:p2s.height-580,size:12,font:activeFont,color:PDFLib.rgb(0,0,0)})}}if(p.engineer_signature_data){try{const certPageIndex=m.key==='pm151'?52:(pdfDoc.getPageCount()>34?34:-1);if(certPageIndex>=0&&certPageIndex<pdfDoc.getPageCount()){const certPage=pdfDoc.getPage(certPageIndex),cps=certPage.getSize(),isPng=p.engineer_signature_data.includes('image/png'),signImg=isPng?await pdfDoc.embedPng(p.engineer_signature_data):await pdfDoc.embedJpg(p.engineer_signature_data);certPage.drawImage(signImg,{x:370,y:cps.height-470,width:110,height:45});if(p.engineer_name){certPage.drawText(`(${p.engineer_name})`,{x:365,y:cps.height-485,size:10,font:activeFont,color:PDFLib.rgb(0,0,0)})}}}catch(se){console.warn('Signature overlay skipped',se)}}const outBytes=await pdfDoc.save(),blob=new Blob([outBytes],{type:'application/pdf'}),url=URL.createObjectURL(blob);downloadURL(url,`${code}-FullReport-56Pages.pdf`);setTimeout(()=>URL.revokeObjectURL(url),10000);toast(`ประกอบเล่มสมบูรณ์ ${pdfDoc.getPageCount()} หน้าและดาวน์โหลดเรียบร้อย!`)}catch(err){console.error(err);toast('ประกอบเล่มไม่สำเร็จ: '+err.message)}}
async function initDB(){db=await new Promise((resolve,reject)=>{let req=indexedDB.open('idc-report-media',1);req.onupgradeneeded=()=>{req.result.createObjectStore('media',{keyPath:'id'});req.result.createObjectStore('documents',{keyPath:'id'})};req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});photos=await dbAll('media');if(!state.hiddenReference){photos.unshift({id:'pdf-reference-pm151',projectId:'pm151',name:'PM.FP.69-151 · หน้า 10',caption:'ภาพอ้างอิงจากรายงานเดิม หน้า 10',category:'Fire Pump',source:true});photoUrls.set('pdf-reference-pm151','assets/fire-pump-reference.png');}if(project().id==='pm151'&&!project().cover&&!state.hiddenReference)project().cover='pdf-reference-pm151';documents=await dbAll('documents');for(const a of photos)if(a.blob)photoUrls.set(a.id,URL.createObjectURL(a.blob));render()}
function dbAll(store){return new Promise((resolve,reject)=>{const req=db.transaction(store).objectStore(store).getAll();req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
function dbWrite(store,item,remove=false){return new Promise((resolve,reject)=>{if(!db){reject(Error('พื้นที่จัดเก็บรูปยังไม่พร้อม'));return}const tx=db.transaction(store,'readwrite');const os=tx.objectStore(store);remove?os.delete(item):os.put(item);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}
async function uploadFiles(files){if(locked())return;const pid=project().id;let added=0;for(const file of files){if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>15*1024*1024){toast('ข้ามไฟล์ที่ไม่ใช่ภาพ หรือใหญ่กว่า 15 MB');continue}try{const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());const hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');if(photos.some(a=>a.projectId===pid&&a.hash===hash))continue;const a={id:crypto.randomUUID(),projectId:pid,name:file.name,caption:'',category:categories[0],blob:file,hash,at:new Date().toISOString()};await dbWrite('media',a);photos.push(a);photoUrls.set(a.id,URL.createObjectURL(file));const p=state.projects.find(p=>p.id===pid);if(!p.cover)p.cover=a.id;added++}catch(e){toast('บันทึกภาพไม่สำเร็จ: '+e.message);break}}persist(`เพิ่มรูป ${added} รูป`);render();toast(`เพิ่มรูปแล้ว ${added} รูป · ข้ามภาพซ้ำอัตโนมัติ`)}
async function printReport(){const p=project(),all=[];for(const s of p.sections){if(s==='appendix'){const list=projectPhotos().filter(a=>!a.source);if(!list.length)all.push([s,null]);else for(let i=0;i<list.length;i+=4)all.push([s,list.slice(i,i+4)])}else all.push([s,null])}$('#print-area').innerHTML=all.map(([s,subset],i)=>paper(s,p,subset,i+1,all.length)).join('');await Promise.all([...$('#print-area').querySelectorAll('img')].map(img=>img.decode()));await document.fonts.ready;window.print()}
const actions={
'reference':()=>{const m=ClassicTemplates.get(project());$('#modal').classList.add('wide-modal');modal(`<div class="reference-heading"><div><h2>PDF ต้นฉบับ · ${m.code}</h2><p>เอกสารอ้างอิง ${m.pages} หน้า — ผลตรวจ รูป และลายเซ็นเดิมไม่ถูกนำไปสร้างผลของงานใหม่</p></div><button data-action="close-modal">ปิด</button></div><div class="reference-layout"><div class="reference-pages">${(TemplateManifest[m.key]||[]).map(pg=>`<button data-reference-page="${pg.page}">${pg.page}. ${esc(pg.title)}${pg.landscape?' ↔':''}</button>`).join('')}</div><object id="reference-frame" data="assets/templates/${m.key}/reference.pdf#page=1" type="application/pdf"><p>หากเบราว์เซอร์ไม่แสดง PDF <a href="assets/templates/${m.key}/reference.pdf" target="_blank" rel="noopener">เปิด PDF ต้นฉบับ</a></p></object></div>`)},
'menu':()=>$('.sidebar').classList.toggle('open'),'close-modal':closeModal,'new-project':()=>projectModal(),'select-project':()=>modal(`<h2>เลือกโครงการ</h2><p>ข้อมูลและรูปภาพจะแยกกันตามโครงการ</p>${state.projects.map(p=>`<button data-open="${p.id}" style="width:100%;justify-content:space-between;margin-bottom:10px">${esc(p.code)} · ${esc(p.customer)} ${icon('arrow')}</button>`).join('')}<div class="actions"><button data-action="close-modal">ปิด</button></div>`),
'upload':()=>{if(!locked())$('#upload').click()},'upload-doc':()=>{if(locked())return;const input=document.createElement('input');input.type='file';input.accept='application/pdf,image/jpeg,image/png';input.multiple=true;const pid=project().id;input.onchange=async()=>{let count=0;for(const file of input.files){if(file.size>25*1024*1024||!['application/pdf','image/jpeg','image/png'].includes(file.type)){toast('รับเฉพาะ PDF/JPG/PNG ไม่เกิน 25 MB');continue}try{const d={id:crypto.randomUUID(),projectId:pid,name:file.name,blob:file,expiry:'',at:new Date().toISOString()};await dbWrite('documents',d);documents.push(d);count++}catch(e){toast('บันทึกเอกสารไม่สำเร็จ');break}}persist(`เพิ่มเอกสาร ${count} ไฟล์`);render();toast(`เพิ่มเอกสารแล้ว ${count} ไฟล์`)};input.click()},
'draft':()=>{if(locked())return;const text=M.narrative(project());modal(`<h2>ร่างสรุปจากข้อมูลที่บันทึก</h2><p>สร้างจากกฎข้อความในต้นแบบ ยังไม่ได้เชื่อม LLM โปรดตรวจทานก่อนนำไปใช้</p><p style="color:var(--ink);white-space:pre-line">${esc(text)}</p><div class="actions"><button data-action="close-modal">ยกเลิก</button><button class="primary" data-action="accept-draft">นำไปใช้เป็นร่างสรุป</button></div>`)},
'accept-draft':()=>{if(mutate(p=>p.summary=M.narrative(p),'สร้างร่างสรุปจากข้อมูล')){section='findings';tab='content';view='builder';closeModal();render();toast('เพิ่มร่างสรุปแล้ว กรุณาตรวจทาน')}},
'qa':()=>{view='inbox';render()},'print':printReport,
'zoom-in':()=>{zoom=Math.min(140,zoom+10);render()},'zoom-out':()=>{zoom=Math.max(70,zoom-10);render()},
'clone':()=>{const p=M.cloneProject(project());state.projects.push(p);state.active=p.id;persist('สร้างงานครั้งใหม่โดยไม่คัดลอกผลตรวจเดิม');view='projects';render();toast('สร้างงานใหม่แล้ว ผลตรวจและรูปหลักฐานเริ่มต้นใหม่')},
'submit':()=>{const issues=M.validate(project(),projectPhotos());if(issues.length){toast(`ยังส่งตรวจไม่ได้: ข้อมูลไม่ครบ ${issues.length} รายการ`);view='inbox';render();return}project().status='SUBMITTED';persist('ส่งตรวจทาน (ทดลอง)');render();toast('ส่งตรวจทานในต้นแบบแล้ว')},
'return':()=>{const note=$('#review-note').value.trim();if(!note){toast('กรุณาระบุเหตุผลที่ส่งกลับแก้ไข');return}if(project().status!=='SUBMITTED')return;project().status='RETURNED';persist('ส่งกลับแก้ไข: '+note);render()},
'approve':()=>{if(project().status!=='SUBMITTED')return;const p=project(),note=$('#review-note').value.trim();if(!note){toast('กรุณาระบุหมายเหตุการตรวจทานก่อนล็อกฉบับ');return}if(M.validate(p,projectPhotos()).length){toast('ข้อมูลยังไม่ครบ');return}const snapshot=JSON.parse(JSON.stringify({...p,snapshots:[],history:[]}));p.snapshots.push({at:new Date().toISOString(),revision:p.revision,note,data:snapshot,mediaMetadata:projectPhotos().map(({blob,...meta})=>meta),mediaIds:projectPhotos().map(a=>a.id),documentIds:projectDocs().map(d=>d.id)});p.status='APPROVED';persist('ล็อกฉบับตรวจทาน (ทดลอง): '+note);render();toast('บันทึก Snapshot แล้ว ไม่มีการลงนามหรือรับรองจริง')},
'revision':()=>{if(project().status!=='APPROVED')return;project().status='DRAFT';project().revision++;persist('เปิด Revision ใหม่ เก็บ Snapshot เดิมไว้');render()},
'backup':()=>downloadJSON(state,'idc-projects-backup.json'),
'export-package':exportPackage,
'import-package':()=>{const inp=$('#import-package-input');if(inp)inp.click()},
'upload-signature':()=>{const inp=$('#signature-input');if(inp)inp.click()},
'remove-signature':()=>{if(mutate(p=>{p.engineer_signature_data=null},'ลบลายเซ็นวิศวกร')){render();toast('ลบลายเซ็นวิศวกรแล้ว')}},
'assemble-pdf':assembleFullPDF,
'guide':()=>modal(`<h2>เริ่มต้นสร้างรายงานของคุณ</h2><p>1. เลือกโครงการ หรือสร้างงานจากปีเดิม<br>2. เพิ่มรูปและจัดหมวดในคลังภาพ<br>3. ตอบแบบตรวจสอบและกรอกค่าที่วัดจริง<br>4. ตรวจพรีวิวและเขียนสรุปผล<br>5. ตรวจข้อมูลที่ขาด แล้วพิมพ์ / บันทึกเป็น PDF</p><p>ต้นแบบทำงานในเครื่อง ไม่มีการส่งข้อมูลขึ้นเซิร์ฟเวอร์ เปิดดูรายละเอียดฟังก์ชันได้ที่หน้าตั้งค่า</p><div class="actions"><a href="user-guide.html" target="_blank" rel="noopener" style="font-size:12px;margin-right:auto">เปิดคู่มือใช้งานฉบับเต็ม ↗</a><button class="primary" data-action="close-modal">เริ่มใช้งาน</button></div>`)
};
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-section]');if(!b)return;try{if(b.dataset.referencePage){const m=ClassicTemplates.get(project());$('#reference-frame').setAttribute('data',`assets/templates/${m.key}/reference.pdf#page=${Number(b.dataset.referencePage)}`);}else if(b.dataset.view){view=b.dataset.view;search='';render();window.scrollTo(0,0)}else if(b.dataset.section){section=b.dataset.section;render()}else if(b.dataset.tab){tab=b.dataset.tab;render()}else if(b.dataset.open){state.active=b.dataset.open;persist();closeModal();render()}else if(b.dataset.template)projectModal(b.dataset.template);else if(b.dataset.answer){const id=b.dataset.answer,v=b.dataset.value;if(mutate(p=>{p.answers[id]={...p.answers[id],value:v}},`บันทึก ${id}: ${v}`))render()}else if(b.dataset.cover){if(mutate(p=>p.cover=b.dataset.cover,'เปลี่ยนภาพหน้าปก'))render()}else if(b.dataset.deletePhoto){if(locked())return;const id=b.dataset.deletePhoto;if(project().snapshots.some(s=>s.mediaIds.includes(id))){toast('รูปนี้อยู่ใน Snapshot เดิม จึงเก็บไว้เป็นหลักฐาน');return}if(id==='pdf-reference-pm151')state.hiddenReference=true;else await dbWrite('media',id,true);photos=photos.filter(a=>a.id!==id);URL.revokeObjectURL(photoUrls.get(id));photoUrls.delete(id);if(project().cover===id)project().cover=null;persist('ลบภาพหลักฐาน');render()}else if(b.dataset.move){const s=b.dataset.move,offset=Number(b.dataset.direction);if(mutate(p=>{let i=p.sections.indexOf(s);[p.sections[i],p.sections[i+offset]]=[p.sections[i+offset],p.sections[i]]},'จัดลำดับส่วนรายงาน'))render()}else if(b.dataset.snapshot){const snap=project().snapshots[Number(b.dataset.snapshot)];downloadJSON(snap,`${project().code}-snapshot-${Number(b.dataset.snapshot)+1}.json`)}else if(b.dataset.downloadDoc){const d=documents.find(d=>d.id===b.dataset.downloadDoc);const u=URL.createObjectURL(d.blob);downloadURL(u,d.name);setTimeout(()=>URL.revokeObjectURL(u),5000)}else if(b.dataset.deleteDoc){if(locked())return;const id=b.dataset.deleteDoc;if(project().snapshots.some(s=>s.documentIds.includes(id))){toast('เอกสารนี้อยู่ใน Snapshot เดิม จึงเก็บไว้เป็นหลักฐาน');return}await dbWrite('documents',id,true);documents=documents.filter(d=>d.id!==id);persist('ลบเอกสารแนบ');render()}else if(b.dataset.action&&actions[b.dataset.action])await actions[b.dataset.action]()}catch(err){console.error(err);toast('ดำเนินการไม่สำเร็จ: '+err.message)}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-section]')){e.preventDefault();e.target.click()}});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='project-search'){search=el.value;$('#project-table').innerHTML=projectTable();return}if(el.dataset.field){const name=el.dataset.field,old=project()[name];let value=el.type==='number'?(el.value===''?null:Number(el.value)):el.value;if(el.validity&&!el.validity.valid)return;if(mutate(p=>p[name]=value,`แก้ไข ${name}`))refreshPreview();else el.value=old??''}else if(el.dataset.remark){const id=el.dataset.remark;mutate(p=>p.answers[id]={...p.answers[id],remark:el.value},`แก้หมายเหตุ ${id}`)}else if(el.dataset.test!==undefined&&el.dataset.metric!=='status'){const i=Number(el.dataset.test),k=el.dataset.metric;if(el.validity&&!el.validity.valid)return;const value=k==='reason'?el.value:el.value===''?null:Number(el.value);if(mutate(p=>p.tests[i][k]=value,`บันทึกผลทดสอบ ${project().tests[i].point}% ${k}`)&&$('#chart-area'))$('#chart-area').innerHTML=chart()}});
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='upload'){await uploadFiles([...el.files]);el.value=''}else if(el.id==='import-package-input'){if(el.files&&el.files[0])await importPackage(el.files[0]);el.value=''}else if(el.id==='signature-input'){const f=el.files&&el.files[0];if(f){const dataUrl=await _b64.toBase64(f);if(mutate(p=>{p.engineer_signature_data=dataUrl},'แนบลายเซ็นวิศวกร')){render();toast('แนบลายเซ็นวิศวกรแล้ว')}}el.value=''}else if(el.dataset.test!==undefined&&el.dataset.metric==='status'){const i=Number(el.dataset.test);if(mutate(p=>{p.tests[i].status=el.value;if(el.value!=='TESTED'){p.tests[i].flow=null;p.tests[i].discharge=null;p.tests[i].suction=null}},`เปลี่ยนสถานะทดสอบ ${project().tests[i].point}%`))render()}else if(el.dataset.photoCategory||el.dataset.photoCaption){if(locked())return;const id=el.dataset.photoCategory||el.dataset.photoCaption,a=photos.find(a=>a.id===id);const updated={...a,[el.dataset.photoCategory?'category':'caption']:el.value};if(a.source){toast('ภาพอ้างอิงเดิมแก้ไขไม่ได้ เพิ่มภาพของคุณเพื่อใช้งาน');el.value=el.dataset.photoCategory?a.category:a.caption;return}await dbWrite('media',updated);Object.assign(a,updated);persist('แก้ข้อมูลภาพหลักฐาน')}else if(el.dataset.docExpiry){if(locked())return;const d=documents.find(d=>d.id===el.dataset.docExpiry),updated={...d,expiry:el.value};await dbWrite('documents',updated);Object.assign(d,updated);persist('แก้วันหมดอายุเอกสาร');render()}}catch(err){toast('บันทึกไม่สำเร็จ: '+err.message)}});
document.addEventListener('submit',e=>{if(e.target.id!=='new-project-form')return;e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(state.projects.some(p=>p.code.trim()===data.code.trim())){toast('เลขที่รายงานซ้ำ กรุณาใช้เลขใหม่');return}const p=M.cloneProject(M.seed().projects[0]);Object.assign(p,data);state.projects.push(p);state.active=p.id;persist('สร้างโครงการใหม่');closeModal();view='projects';render();toast('สร้างโครงการแล้ว')});
window.addEventListener('offline',()=>toast('ออฟไลน์ · ยังบันทึกฟอร์มในเครื่องได้'));window.addEventListener('online',()=>toast('เชื่อมต่ออินเทอร์เน็ตแล้ว · ต้นแบบไม่มีการซิงก์เซิร์ฟเวอร์'));
render();initDB().catch(e=>{console.error(e);toast('ไม่สามารถเปิดพื้นที่เก็บรูปในเบราว์เซอร์นี้ได้')});
